import { createPrivacyPolicyPageService, getPrivacyPolicyPageService, updatePrivacyPolicyPageService, deletePrivacyPolicyPageService, } from "../services/privacyPolicyPage.service.js";
import { triggerRevalidation } from "../utils/revalidate.js";
export const createPrivacyPolicyPage = async (req, res) => {
    try {
        const page = await createPrivacyPolicyPageService(req.body);
        triggerRevalidation();
        res.status(201).json({ success: true, data: page });
    }
    catch (error) {
        const err = error;
        res.status(err.statusCode || 500).json({ success: false, message: err.message });
    }
};
export const getPrivacyPolicyPage = async (req, res) => {
    try {
        const slug = req.query.slug;
        const lang = req.query.lang;
        if (!slug) {
            res.status(400).json({ success: false, message: "slug query param is required" });
            return;
        }
        if (lang && lang !== "en" && lang !== "ar") {
            res.status(400).json({ success: false, message: "Invalid lang. Use 'en' or 'ar'" });
            return;
        }
        const page = await getPrivacyPolicyPageService(slug, lang);
        res.status(200).json({ success: true, data: page });
    }
    catch (error) {
        const err = error;
        res.status(err.statusCode || 500).json({ success: false, message: err.message });
    }
};
export const updatePrivacyPolicyPage = async (req, res) => {
    try {
        const slug = req.query.slug;
        if (!slug) {
            res.status(400).json({ success: false, message: "slug query param is required" });
            return;
        }
        const page = await updatePrivacyPolicyPageService(slug, req.body);
        triggerRevalidation();
        res.status(200).json({ success: true, data: page });
    }
    catch (error) {
        const err = error;
        res.status(err.statusCode || 500).json({ success: false, message: err.message });
    }
};
export const deletePrivacyPolicyPage = async (req, res) => {
    try {
        const slug = req.query.slug;
        if (!slug) {
            res.status(400).json({ success: false, message: "slug query param is required" });
            return;
        }
        await deletePrivacyPolicyPageService(slug);
        triggerRevalidation();
        res.status(200).json({ success: true, message: "Privacy policy page deleted successfully" });
    }
    catch (error) {
        const err = error;
        res.status(err.statusCode || 500).json({ success: false, message: err.message });
    }
};
